import React, { useState, useEffect, useRef } from 'react';
import ContentList from '../components/ContentList';

const exercises = [
  { id: 1, title: 'Nivel Básico', text: 'hola mundo esta es una prueba de mecanografia' },
  { id: 2, title: 'Teclas comunes', text: 'asdf jkl; asdf jkl; asdf jkl;' },
  { id: 3, title: 'Frase larga', text: 'la practica hace al maestro, escribe con calma y constancia' },
];

const ContentPage = () => {
  const [index, setIndex] = useState(0);
  const [input, setInput] = useState('');
  const [startedAt, setStartedAt] = useState(null);
  const [finished, setFinished] = useState(false);
  const inputRef = useRef(null);

  useEffect(() => {
    setInput('');
    setStartedAt(null);
    setFinished(false);
    inputRef.current && inputRef.current.focus();
  }, [index]);

  const current = exercises[index];

  const handleChange = (e) => {
    if (!startedAt) setStartedAt(Date.now());
    const val = e.target.value;
    setInput(val);
    if (val.trim() === current.text.trim()) {
      setFinished(true);
    }
  };

  const elapsedSeconds = startedAt ? (Date.now() - startedAt) / 1000 : 0;
  const words = input.trim() ? input.trim().split(/\s+/).length : 0;
  const wpm = elapsedSeconds > 0 ? Math.round((words / (elapsedSeconds / 60))) : 0;

  return (
    <main style={{ padding: '1rem' }}>
      <h1>Ejercicios de Mecanografía</h1>
      <section style={{ marginBottom: '1.5rem' }}>
        <h2>{current.title}</h2>
        <div style={{ padding: '1rem', border: '1px solid #ddd', borderRadius: 6, background: '#fafafa' }}>
          <p>{current.text}</p>
        </div>
        <textarea
          ref={inputRef}
          value={input}
          onChange={handleChange}
          placeholder="Empieza a escribir aquí..."
          rows={4}
          style={{ width: '100%', marginTop: '1rem' }}
        />

        <div style={{ marginTop: '0.75rem' }}>
          <strong>WPM:</strong> {wpm} {finished && <span style={{ color: 'green' }}> — Completado 🎉</span>}
        </div>

        <div style={{ marginTop: '1rem' }}>
          <button onClick={() => setIndex((i) => (i + 1) % exercises.length)}>Siguiente ejercicio</button>
          <button onClick={() => { setInput(''); setStartedAt(null); setFinished(false); }} style={{ marginLeft: '0.5rem' }}>Reiniciar</button>
        </div>
      </section>

      <section>
        <h2>Lista de ejercicios</h2>
        <ContentList />
      </section>
    </main>
  );
};

export default ContentPage;
